// ── Node 2: Input File Validation ────────────────────────────────────
// Validates required fields from the webhook body.
// Returns an error early if required files are missing.

const body = $input.first().json;
const jobId = body.job_id;
const paperPath = body.paper_path;
const outputDir = body.output_dir;

if (!jobId) throw new Error('Missing job_id in request body');
if (!paperPath) throw new Error('Missing paper_path in request body');
if (!outputDir) throw new Error('Missing output_dir in request body');

// Pass validated data to next nodes
return [{
  json: {
    job_id: jobId,
    paper_path: paperPath,
    template_path: body.template_path || null,
    output_dir: outputDir,
    validated: true,
    timestamp: new Date().toISOString(),
  }
}];

// ── Check Stage A exit code ──────────────────────────────────────────
const result = $input.first().json;
const exitCode = result.exitCode;
const stderr = result.stderr || '';

if (exitCode !== 0) {
  throw new Error(
    `Stage A (Extract Document) failed with exit code ${exitCode}.\n${stderr}`
  );
}

return [{ json: { ...result, stage_a_ok: true } }];

// ── Merge Stage B1 and B2 results ───────────────────────────────────
// Both Zotero fetch and online verification run in parallel.
// This node merges their outputs before proceeding.

const results = $input.all();
const anyFailed = results.some(r => r.json.exitCode && r.json.exitCode !== 0);
if (anyFailed) {
  const failed = results.find(r => r.json.exitCode !== 0);
  throw new Error(
    `A verification stage failed: ${failed.json.stderr || 'Unknown error'}`
  );
}

return [{ json: { ...results[0].json, verification_complete: true } }];

const result = $input.first().json;
if (result.exitCode !== 0) {
  throw new Error(
    `Stage C+D (Citation Mapping) failed: ${result.stderr || ''}`
  );
}
return [{ json: { ...result, mapping_complete: true } }];

// ── Final Quality Checks and Response ───────────────────────────────
const result = $input.first().json;

// Collect all expected outputs
const expectedFiles = [
  'IEEE_Formatted_Research_Paper.docx',
  'Original_Research_Paper_Backup.docx',
  'Citation_Verification_Report.csv',
  'Text_Preservation_Report.txt',
  'Unresolved_Citations_Report.txt',
];

const outputDir = result.output_dir;
const timestamp = new Date().toISOString();

return [{
  json: {
    status: 'complete',
    job_id: result.job_id,
    timestamp,
    output_dir: outputDir,
    expected_files: expectedFiles,
    message: (
      'Processing complete. Review Unresolved_Citations_Report.txt before ' +
      'submitting. Check Text_Preservation_Report.txt to confirm original ' +
      'text was not modified.'
    )
  }
}];
